#pragma once
#include <juce_gui_extra/juce_gui_extra.h>
namespace PulseTheme {
 inline const juce::Colour bgPrimary{0xff080c11},cyan{0xff14e8c6},panel{0xff0e151e},header{0xff0b1118},border{0xff233447},text{0xffe2e8f0},muted{0xff94a3b8},active{0xff0c3638},button{0xff131d29};
 inline juce::Font font(float size,bool bold=false){return juce::Font(size,bold?juce::Font::bold:juce::Font::plain);}
 inline void style(juce::Label& l,float size,bool bold=false,juce::Colour c=text){l.setFont(font(size,bold));l.setColour(juce::Label::textColourId,c);}
 inline void apply(juce::LookAndFeel& l){l.setColour(juce::Slider::thumbColourId,cyan);l.setColour(juce::TextButton::buttonColourId,button);l.setColour(juce::TextButton::textColourOffId,text);l.setColour(juce::TextButton::textColourOnId,text);l.setColour(juce::ComboBox::backgroundColourId,panel);l.setColour(juce::ComboBox::outlineColourId,border);l.setColour(juce::Label::textColourId,text);l.setColour(juce::ListBox::backgroundColourId,panel);l.setColour(juce::TextButton::buttonOnColourId,active);l.setColour(juce::TextButton::textColourOnId,cyan);l.setColour(juce::ComboBox::textColourId,text);l.setColour(juce::TextEditor::backgroundColourId,bgPrimary);l.setColour(juce::TextEditor::textColourId,text);l.setColour(juce::TextEditor::outlineColourId,border);l.setColour(juce::Slider::textBoxBackgroundColourId,bgPrimary);l.setColour(juce::Slider::textBoxTextColourId,text);l.setColour(juce::Slider::textBoxOutlineColourId,border);l.setColour(juce::Slider::trackColourId,cyan);l.setColour(juce::PopupMenu::backgroundColourId,panel);l.setColour(juce::PopupMenu::textColourId,text);}
}
